public void handleCompanyChangedEvent(
        CompanyChangedEvent event
) {
    if (processedEvents.exists(event.eventId())) {
        return;
    }

    if (!isRelevant(event)) {
        processedEvents.save(event.eventId());
        return;
    }

    coverageService.recalculateForCompany(
        event.companyId()
    );

    processedEvents.save(event.eventId());
}
